import sys
from datetime import datetime

def parse_time(time_str):
    h, m = map(int, time_str.split(':'))
    return datetime.combine(datetime.min, datetime.time(h, m))

def format_time(duration):
    total_minutes = duration.total_seconds() / 60
    hours = int(total_minutes // 60)
    minutes = int(total_minutes % 60)
    return f"{hours}:{minutes:02d}"


def main():
    bookings = []
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "book":
            bid, room, day, start, end = parts[1:]
            start_time = parse_time(start)
            end_time = parse_time(end)
            if end_time <= start_time:
                print("INVALID", bid)
                continue
            conflict = None
            for other_bid, other_room, other_day, other_start, other_end in bookings:
                if other_room == room and other_day == day and not (end_time <= other_start or start_time <= other_end):
                    conflict = other_bid
                    break
            if conflict:
                print("REJECT", bid, conflict)
            else:
                bookings.append((bid, room, day, start_time, end_time))
                print("ACCEPT", bid)
        elif parts[0] == "cancel":
            bookings = [b for b in bookings if b[0] != parts[1]]
            print("CANCELLED", parts[1])
    rooms = {}
    for bid, room, day, start_time, end_time in bookings:
        rooms[room] = rooms.get(room, 0) + 1
    for room in sorted(rooms):
        total_duration = sum((end_time - start_time).total_seconds() / 60 for start_time, end_time in [
            (b[3], b[4]) for b in bookings if b[1] == room])
        print(room, rooms[room], format_time(total_duration))


if __name__ == "__main__":
    main()
